import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.oAolcYhj.js";const g=JSON.parse('{"title":"2. Arbeiten mit Qonnectra","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/02-arbeiten-mit-qonnectra.md","filePath":"manual/teil-a-anwenderhandbuch/02-arbeiten-mit-qonnectra.md"}'),a={name:"manual/teil-a-anwenderhandbuch/02-arbeiten-mit-qonnectra.md"};function s(d,e,o,l,h,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-arbeiten-mit-qonnectra" tabindex="-1">2. Arbeiten mit Qonnectra <a class="header-anchor" href="#_2-arbeiten-mit-qonnectra" aria-label="Permalink to &quot;2. Arbeiten mit Qonnectra&quot;">​</a></h1><p>Qonnectra ist kein Planungswerkzeug für neue Glasfasernetze. Es ist für die <strong>Dokumentation</strong> und <strong>Verwaltung des passiven Netzbestands</strong> ausgelegt, also für die Bestandteile eines Netzes, die keine aktive Technik wie Ports, Bandbreiten oder Betriebsdaten benötigen. Dieses Kapitel beschreibt, was das für die tägliche Arbeit bedeutet: worauf sich die angezeigten Daten beziehen und was Sie in der Webanwendung ändern können.</p><h2 id="_2-1-ziele-der-dokumentation" tabindex="-1">2.1 Ziele der Dokumentation <a class="header-anchor" href="#_2-1-ziele-der-dokumentation" aria-label="Permalink to &quot;2.1 Ziele der Dokumentation&quot;">​</a></h2><p>Die <strong>Webanwendung</strong> dient der strukturierten Einsicht, Dokumentation und Auswertung des Netzbestands. Sie ist bewusst reduziert gestaltet, um auch ohne GIS-Vorkenntnisse genutzt werden zu können, und bereitet Trassen, Verlegearten, Oberflächen, Netzebenen, Netzknoten und Gewährleistungsstände projektbezogen auf. Der Fokus liegt dabei auf drei Zielen:</p><ul><li><strong>Transparenz schaffen</strong> über den dokumentierten Ausbauzustand,</li><li><strong>Wissen sichern</strong>, etwa für Rückfragen von Ämtern, beteiligten Organisationen oder Förderinstitutionen,</li><li><strong>Komplexität reduzieren</strong> durch eine klare, nicht überladene Benutzeroberfläche.</li></ul><h2 id="_2-2-das-projekt-als-bezugsgroße" tabindex="-1">2.2 Das Projekt als Bezugsgröße <a class="header-anchor" href="#_2-2-das-projekt-als-bezugsgroße" aria-label="Permalink to &quot;2.2 Das Projekt als Bezugsgröße&quot;">​</a></h2><p>Alle Daten in Qonnectra gehören zu einem <strong>Projekt</strong>. Welches Projekt gilt, wählen Sie oben links in der Kopfzeile; die Auswahl gilt für die gesamte Anwendung und bleibt beim Wechsel in eine andere Ansicht erhalten. Kennzahlen, Karteninhalte und Listen zeigen deshalb immer nur den Bestand des ausgewählten Projekts, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Nur in den Kartenansichten lässt sich diese Beschränkung über „Alle Projekte anzeigen“ vorübergehend aufheben. Welche Projekte in der Auswahl stehen, hängt von Ihrem Benutzerkonto ab.</p></div><h2 id="_2-3-ansehen-und-bearbeiten" tabindex="-1">2.3 Ansehen und Bearbeiten <a class="header-anchor" href="#_2-3-ansehen-und-bearbeiten" aria-label="Permalink to &quot;2.3 Ansehen und Bearbeiten&quot;">​</a></h2><p>Der größte Teil der Anwendung ist zur Ansicht bestimmt: Das Dashboard wertet den Bestand aus, die Karte zeigt die Objekte mit ihren Eigenschaften – geändert wird an beiden Stellen nichts. Anlegen und bearbeiten können Sie</p><ul><li>Rohre und ihre Eigenschaften in der <strong>Rohrverwaltung</strong>, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a>,</li><li>die Zuordnung von Rohren zu Trassensegmenten in der <strong>Rohrzuordnung</strong>, siehe Kapitel <a href="./07-rohrzuordnung.html">Rohrzuordnung</a>,</li><li>Anhänge (Dateien) an Kartenobjekten und an Rohren, siehe Abschnitt <a href="./05-karte.html#_5-3-1-anhange-von-kartenobjekten">Anhänge von Kartenobjekten</a>.</li></ul><p>Die <strong>Geometrie</strong> – der Verlauf einer Trasse, die Lage eines Netzknotens oder der Zuschnitt eines Gebiets – wird nicht in der Webanwendung bearbeitet, sondern in QGIS. Beide greifen auf dieselbe Datenbasis zu; das Vorgehen beschreibt Teil B des Handbuchs.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Welche Menüpunkte Sie sehen und was Sie darin ändern dürfen, hängt von den Rechten Ihres Benutzerkontos ab. Fehlt ein in diesem Handbuch genannter Bereich, ist er für Ihr Konto nicht freigegeben – wenden Sie sich in diesem Fall an Ihre Administration.</p></div><h2 id="_2-4-ein-typischer-arbeitsablauf" tabindex="-1">2.4 Ein typischer Arbeitsablauf <a class="header-anchor" href="#_2-4-ein-typischer-arbeitsablauf" aria-label="Permalink to &quot;2.4 Ein typischer Arbeitsablauf&quot;">​</a></h2><p>Für den Einstieg hat sich die folgende Reihenfolge bewährt:</p><ol><li>Melden Sie sich an und machen Sie sich mit dem Aufbau der Oberfläche vertraut, siehe Kapitel <a href="./03-einstieg-und-anmeldung.html">Einstieg und Anmeldung</a>.</li><li>Wählen Sie oben links in der Kopfzeile das Projekt aus, mit dem Sie arbeiten möchten.</li><li>Verschaffen Sie sich im Dashboard einen Überblick über den Ausbauzustand, siehe Kapitel <a href="./04-dashboard.html">Dashboard</a>.</li><li>Sehen Sie sich einzelne Objekte in der Karte an und rufen Sie deren Eigenschaften und Anhänge ab, siehe Kapitel <a href="./05-karte.html">Karte</a>.</li><li>Pflegen Sie Rohre in der Rohrverwaltung und ordnen Sie sie anschließend den Trassensegmenten zu, siehe Kapitel <a href="./06-rohrverwaltung.html">Rohrverwaltung</a> und <a href="./07-rohrzuordnung.html">Rohrzuordnung</a>.</li></ol><p>Die Kapitel von Teil A folgen dieser Reihenfolge.</p>',17)])])}const c=n(a,[["render",s]]);export{g as __pageData,c as default};
